  selector: 'app-dashboard',
  standalone: true,
  template: `
    <!-- 1. Signal Binding (Zero manual subscriptions!) -->
    <div>Active Users: {{ activeUsers() }}</div>

    <!-- 2. Async Pipe Binding -->
    @if (metrics$ | async; as metrics) {
      <p>CPU: {{ metrics.cpu }}%</p>
    }
  `
})
export class DashboardComponent {
